/* C side of the heap probes (crates/hirsel-llvm/tests/native.rs, `heap_program`).
 *
 * Each entry allocates heap blocks through hirsel_rt_v2_alloc or hirsel_rt_v2_reuse and frees
 * them with hirsel_rt_v2_release or hirsel_rt_v2_reset, using the layout descriptors the
 * object carries. The runtime runs in diagnostic mode, and its live block count must return
 * to where it started, on success and failure paths alike. `entries.h` (generated by
 * `hirsel_llvm::c_call`) defines `call_<entry>` of each entry's ABI v1 signature. */
#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "hirsel_rt_v2.h"
#include "entries.h"

typedef hirsel_rt_v2_ctx ctx_t;

static ctx_t *ctx;

static uint64_t live(void) {
  hirsel_rt_v2_stats stats;
  hirsel_rt_v2_ctx_stats(ctx, &stats);
  return stats.live_blocks;
}

static void report(const char *name, uint8_t s, int64_t value) {
  printf("%s ", name);
  if (s == 0) {
    printf("ok %" PRId64 "\n", value);
    return;
  }
  hirsel_rt_v2_failure f;
  if (s != 1 || !hirsel_rt_v2_failure_primary(ctx, &f)) {
    printf("bad status %u\n", (unsigned)s);
    return;
  }
  printf("fail %u %u %016" PRIx64 "\n", f.kind, f.rule, f.site);
  hirsel_rt_v2_failure_clear(ctx);
}

#define CASE(name, entry, ...)                    \
  do {                                            \
    int64_t r_ = 0;                               \
    uint8_t s_ = entry(ctx, &r_, __VA_ARGS__);    \
    report(name, s_, r_);                         \
  } while (0)

int main(void) {
  hirsel_rt_v2_config config;
  memset(&config, 0, sizeof config);
  config.abi_version = HIRSEL_RT_V2_ABI_VERSION;
  config.flags = HIRSEL_RT_V2_CONFIG_DIAGNOSTIC;
  if (hirsel_rt_v2_ctx_create(&config, &ctx) != 0) {
    printf("no context\n");
    return 1;
  }
  uint64_t base = live();
  CASE("box_roundtrip 7", call_box_roundtrip, 7);
  CASE("box_roundtrip min", call_box_roundtrip, INT64_MIN);
  CASE("nested 3 4", call_nested, 3, 4);
  CASE("list_get 0", call_list_get, 10, 20, 30, 0);
  CASE("list_get 2", call_list_get, 10, 20, 30, 2);
  CASE("list_get 3", call_list_get, 10, 20, 30, 3);
  CASE("reuse 1 2", call_reuse, 1, 2);
  printf("live after one round %" PRIu64 "\n", live() - base);

  /* Many rounds, failures included: storage is recycled, never leaked. */
  int64_t sum = 0;
  int64_t r;
  unsigned failures = 0;
  for (int i = 0; i < 10000; i++) {
    sum += call_box_roundtrip(ctx, &r, i) == 0 ? r : 0;
    sum += call_nested(ctx, &r, i, -i) == 0 ? r : 0;
    sum += call_reuse(ctx, &r, -i, i) == 0 ? r : 0;
    if (call_list_get(ctx, &r, i, i, i, (uint64_t)(i % 4)) == 0) {
      sum += r;
    } else {
      failures++;
      hirsel_rt_v2_failure_clear(ctx);
    }
  }
  printf("rounds %" PRId64 " failures %u live %" PRIu64 "\n", sum, failures, live() - base);
  hirsel_rt_v2_ctx_destroy(ctx);
  return 0;
}
